(function(){"use strict";const e=document.querySelectorAll(".filter-btn"),a=document.querySelectorAll("[data-category]");!e.length||!a.length||e.forEach(c=>{c.addEventListener("click",()=>{e.forEach(t=>t.classList.remove("active")),c.classList.add("active");const r=c.getAttribute("data-filter");a.forEach(t=>{const l=r==="all"||t.getAttribute("data-category")===r;t.classList.toggle("hidden",!l)})})})})();
